import { useState, useEffect, useCallback } from 'react'

const INITIAL_RATES = {
  USD: { name: 'US Dollar',          symbol: '$',    decimal: 2, rate: 1.00 },
  KRW: { name: 'South Korean Won',   symbol: '₩',    decimal: 0, rate: 1300 },
  EUR: { name: 'Euro',               symbol: '€',    decimal: 2, rate: 0.92 },
  JPY: { name: 'Japanese Yen',       symbol: '¥',    decimal: 0, rate: 145.5 },
  CNY: { name: 'Chinese Yuan',       symbol: '¥',    decimal: 2, rate: 7.15 },
  GBP: { name: 'British Pound',      symbol: '£',    decimal: 2, rate: 0.81 },
  CAD: { name: 'Canadian Dollar',    symbol: 'C$',   decimal: 2, rate: 1.35 },
  THB: { name: 'Thai Baht',          symbol: '฿',    decimal: 2, rate: 35.0 },
  VND: { name: 'Vietnamese Dong',    symbol: '₫',    decimal: 0, rate: 24500 },
  SGD: { name: 'Singapore Dollar',   symbol: 'S$',   decimal: 2, rate: 1.34 },
  HKD: { name: 'Hong Kong Dollar',   symbol: 'HK$',  decimal: 2, rate: 7.82 },
  MXN: { name: 'Mexican Peso',       symbol: 'Mex$', decimal: 2, rate: 18.0 },
  INR: { name: 'Indian Rupee',       symbol: '₹',    decimal: 2, rate: 83.0 },
  IDR: { name: 'Indonesian Rupiah',  symbol: 'Rp',   decimal: 0, rate: 15500 },
  TRY: { name: 'Turkish Lira',       symbol: '₺',    decimal: 2, rate: 29.5 },
  BRL: { name: 'Brazilian Real',     symbol: 'R$',   decimal: 2, rate: 5.10 },
  ZAR: { name: 'South African Rand', symbol: 'R',    decimal: 2, rate: 19.5 },
  CHF: { name: 'Swiss Franc',        symbol: 'Fr',   decimal: 2, rate: 0.90 },
  AUD: { name: 'Australian Dollar',  symbol: 'A$',   decimal: 2, rate: 1.50 },
  NZD: { name: 'New Zealand Dollar', symbol: 'NZ$',  decimal: 2, rate: 1.62 },
}

export default function CurrencyExchange() {
  const [rates, setRates]     = useState(INITIAL_RATES)
  const [amount, setAmount]   = useState('1')
  const [base, setBase]       = useState('USD')
  const [status, setStatus]   = useState('idle') // idle | loading | live | error

  useEffect(() => {
    setStatus('loading')
    fetch('https://open.er-api.com/v6/latest/USD', { signal: AbortSignal.timeout(5000) })
      .then(r => r.json())
      .then(data => {
        if (data.result !== 'success') throw new Error()
        setRates(prev => {
          const next = { ...prev }
          Object.keys(next).forEach(k => {
            if (data.rates[k]) next[k] = { ...next[k], rate: data.rates[k] }
          })
          return next
        })
        setStatus('live')
      })
      .catch(() => setStatus('error'))
  }, [])

  const num = parseFloat(amount) || 0
  const baseRate = rates[base]?.rate ?? 1

  function converted(code) {
    return (num / baseRate * rates[code].rate).toFixed(rates[code].decimal)
  }

  return (
    <div>
      <h3 style={titleStyle}>CURRENCY EXCHANGE</h3>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
        <span style={{
          fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 4,
          background: status === 'live' ? 'rgba(74,222,128,0.15)' : 'rgba(251,191,36,0.15)',
          color: status === 'live' ? 'var(--val-pos)' : 'var(--val-warn)',
          border: `1px solid ${status === 'live' ? 'var(--val-pos)' : 'var(--val-warn)'}`,
        }}>
          {status === 'live' ? '● LIVE' : status === 'loading' ? '● LOADING' : status === 'error' ? '⚠ CACHED' : '● INIT'}
        </span>
        <span style={{ fontSize: 11, color: 'var(--tx-muted)' }}>Source: ExchangeRate-API (open.er-api.com)</span>
      </div>

      {/* Base input */}
      <div style={{ display: 'flex', gap: 10, marginBottom: 20, alignItems: 'center' }}>
        <select value={base} onChange={e => setBase(e.target.value)} style={selectStyle}>
          {Object.keys(rates).map(k => (
            <option key={k} value={k}>{k} — {rates[k].name}</option>
          ))}
        </select>
        <input type="number" value={amount} onChange={e => setAmount(e.target.value)}
          style={{ ...inputStyle, width: 180, textAlign: 'right', fontSize: 18, fontWeight: 700 }} />
      </div>

      {/* Output grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10 }}>
        {Object.entries(rates).map(([code, info]) => (
          <div key={code} style={{
            background: code === base ? 'var(--bg-active)' : 'var(--bg-card)',
            border: `1px solid ${code === base ? 'var(--bd-accent)' : 'var(--bd-subtle)'}`,
            borderRadius: 8, padding: 12, textAlign: 'center',
            cursor: 'pointer',
          }} onClick={() => setBase(code)}>
            <div style={{ fontSize: 10, color: 'var(--tx-muted)', marginBottom: 2 }}>{code}</div>
            <div style={{ fontSize: 11, color: 'var(--tx-secondary)', marginBottom: 6 }}>{info.name}</div>
            <div style={{ fontSize: 17, fontWeight: 700, color: code === base ? 'var(--ac-main)' : 'var(--val-pos)' }}>
              {info.symbol} {converted(code)}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

const titleStyle  = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const selectStyle = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '8px 10px', fontSize: 13, minWidth: 220 }
const inputStyle  = { background: 'var(--bg-input)', border: '1px solid var(--bd-accent)', borderRadius: 6, color: 'var(--tx-primary)', padding: '8px 12px', fontSize: 14 }
